def signal(obs):
    s = obs.state
    if "ema" not in s:
        s["ema"] = {}
    assets = ["A", "B", "C", "IDX"]
    pos = {}
    for asset in assets:
        h = obs.hist(asset, "mid", 60)
        if len(h) < 55:
            continue
        cur = h[-1]
        if cur != cur:
            continue
        # past returns
        v20 = h[-21]
        v50 = h[-51]
        # check nans
        r20 = cur - v20 if v20 == v20 else 0.0
        r50 = cur - v50 if v50 == v50 else 0.0
        if asset == "B":
            raw = r20
            scale = 18.0
        elif asset == "C":
            raw = 0.5 * r20 + 0.5 * r50
            scale = 30.0
        elif asset == "IDX":
            raw = 0.7 * r20 + 0.3 * r50
            scale = 15.0
        else:  # A
            raw = 0.6 * r20 + 0.4 * r50
            scale = 14.0
        alpha = raw / scale
        if alpha > 1:
            alpha = 1
        if alpha < -1:
            alpha = -1
        prev = s["ema"].get(asset, alpha)
        ema = 0.4 * alpha + 0.6 * prev
        s["ema"][asset] = ema
        if abs(ema) < 0.15:
            ema = 0
        pos[asset] = float(ema)
    return pos

