    hA=obs.hist("A","mid",80); hB=obs.hist("B","mid",80); hC=obs.hist("C","mid",80); hI=obs.hist("IDX","mid",80)
    sd=28.0
    if len(hA)>=80:
        syn_h=0.3333*hA+0.6667*hB+0.1667*hC
        prem_h=hI-syn_h
        sd=float(np.nanstd(prem_h))
        if sd!=sd or sd<12: sd=28.0
        if sd>50: sd=50
    z=prem/sd
    thr=1.8
    idx_sig=0
    if abs(z)>=thr:
        zz=z
        if zz>3.5: zz=3.5
        if zz<-3.5: zz=-3.5
        mag=(abs(zz)-thr)/(3.5-thr)
        idx_sig = -(1 if zz>0 else -1)*mag
    mom_sig={}
    for a,scale,w in [("A.X",15,0.35),("B.X",12,0.2)]:
        h=obs.hist(a,"mid",60)
        if len(h)>=35:
            cur=h[-1]; lag=h[-21]
            if cur==cur and lag==lag:
                raw=(cur-lag)/scale
                if raw>1: raw=1
                if raw<-1: raw=-1
                prev=s["e"].get(a,0)
                ema=0.3*raw+0.7*prev
                s["e"][a]=ema
                if abs(ema)>0.3:
                    mom_sig[a]=ema*w
    arb={"IDX":idx_sig, "A": -idx_sig*0.3333, "B": -idx_sig*0.6667, "C": -idx_sig*0.1667}
    combined={}
    for k in ["IDX","A","B","C","A.X","B.X"]:
        v=arb.get(k,0)
        if k in mom_sig:
            v+=mom_sig[k]
        if v>1: v=1
        if v<-1: v=-1
        combined[k]=v
    out={}
    alpha=0.35
    for k,v in combined.items():
        prev=s["p"].get(k,0)
        if abs(v)<0.02:
            ema=prev*0.7
        else:
            ema=alpha*v + (1-alpha)*prev
        s["p"][k]=ema
        if abs(ema)>0.04:
            out[k]=ema
    return out

